import React from 'react';
import { useNavigate } from 'react-router-dom';
import { createProject } from '../api/projects';

const AutoDeliveryEntry: React.FC = () => {
  const navigate = useNavigate();

  const handleStartProject = async () => {
    // 调用API创建新项目，初始状态为REQUIREMENT
    const response = await createProject({ requirement: '' });
    navigate(`/project/${response.projectId}/conversation`);
  };

  return (
    <div className="entry-container">
      <h1>自动化项目交付</h1>
      <p>通过多轮对话自动完成软件交付全流程</p>
      <button onClick={handleStartProject}>新建自动化项目</button>
    </div>
  );
};

export default AutoDeliveryEntry;

import React, { useState, useEffect } from 'react';
