interface Message {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

const ConversationPanel: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [messages, setMessages] = useState<Message[]>([
    { role: 'system', content: '请描述您的项目需求，我将帮助您生成PRD。' }
  ]);
  const [currentPRDDraft, setCurrentPRDDraft] = useState<any>(null);
  const [isConfirmed, setIsConfirmed] = useState(false);

  const handleSendMessage = async (content: string) => {
    // 调用后端对话API，获取助手回复
    // 更新messages和currentPRDDraft
  };

  const handleConfirmPRD = async () => {
    await submitPRD(projectId!, { prdContent: currentPRDDraft, isConfirmed: true });
    setIsConfirmed(true);
    // 跳转到角色分配页面
  };

  if (isConfirmed) {
    return <div>PRD已确认，正在进入角色分配阶段...</div>;
  }

  return (
    <div className="conversation-panel">
      <div className="message-list">
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.role}`}>
            {msg.content}
          </div>
        ))}
      </div>
