import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { submitRoles, getTeamMembers } from '../api/projects';

const STANDARD_ROLES = ['PRODUCT_MANAGER', 'ARCHITECT', 'FRONTEND_ENGINEER', 'BACKEND_ENGINEER', 'TEST_MANAGER'];

const RoleAssignmentPanel: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [selectedRoles, setSelectedRoles] = useState<string[]>([]);
  const [roleMemberMap, setRoleMemberMap] = useState<Record<string, string>>({});
  const [teamMembers, setTeamMembers] = useState<any[]>([]);

  useEffect(() => {
    // 获取平台成员列表
    getTeamMembers().then(setTeamMembers);
  }, []);

  const toggleRole = (role: string) => {
    setSelectedRoles(prev =>
      prev.includes(role) ? prev.filter(r => r !== role) : [...prev, role]
    );
  };

  const assignMember = (role: string, userId: string) => {
    setRoleMemberMap(prev => ({ ...prev, [role]: userId }));
  };

  const handleConfirm = async () => {
    const roles = selectedRoles.map(role => ({
      roleName: role,
      assignedUserId: roleMemberMap[role]
    }));
    await submitRoles(projectId!, { roles });
    // 跳转到架构设计阶段
  };

  return (
    <div className="role-assignment-panel">
      <h2>选择项目角色并指定成员</h2>
      {STANDARD_ROLES.map(role => (
        <div key={role} className="role-item">
          <label>
            <input
              type="checkbox"
              checked={selectedRoles.includes(role)}
              onChange={() => toggleRole(role)}
            />
            {role.replace(/_/g, ' ')}
          </label>
          {selectedRoles.includes(role) && (
            <select
              value={roleMemberMap[role] || ''}
              onChange={e => assignMember(role, e.target.value)}
            >
              <option value="">请选择成员</option>
              {teamMembers.map(member => (
                <option key={member.id} value={member.id}>{member.name}</option>
              ))}
            </select>
          )}
        </div>
      ))}
      <button onClick={handleConfirm} disabled={selectedRoles.length === 0}>
        确认配置并进入下一阶段
      </button>
    </div>
  );
};

export default RoleAssignmentPanel;

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getProjectStatus, getArtifacts } from '../api/projects';
import ArtifactViewer from './ArtifactViewer';

const ProjectDashboard: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [currentPhase, setCurrentPhase] = useState('');
  const [artifacts, setArtifacts] = useState<any[]>([]);
  const [selectedArtifact, setSelectedArtifact] = useState<any>(null);

  useEffect(() => {
    const fetchData = async () => {
      const status = await getProjectStatus(projectId!);
      setCurrentPhase(status.currentPhase);
      const arts = await getArtifacts(projectId!);
      setArtifacts(arts.artifacts);
    };
    fetchData();
    const interval = setInterval(fetchData, 5000); // 轮询更新
    return () => clearInterval(interval);
  }, [projectId]);

  return (
    <div className="project-dashboard">
      <h2>项目工作台</h2>
      <div className="phase-indicator">当前阶段: {currentPhase}</div>
      <div className="artifact-list">
        <h3>工作产物</h3>
        {artifacts.map(artifact => (
          <div
            key={artifact.id}
            className="artifact-item"
            onClick={() => setSelectedArtifact(artifact)}
          >
            {artifact.title} ({artifact.type})
          </div>
        ))}
      </div>
      {selectedArtifact && (
        <ArtifactViewer artifact={selectedArtifact} />
      )}
    </div>
  );
};

export default ProjectDashboard;

import React from 'react';

interface ArtifactViewerProps {
  artifact: {
    type: string;
    content: any;
    readOnly: boolean;
  };
}

const ArtifactViewer: React.FC<ArtifactViewerProps> = ({ artifact }) => {
  return (
    <div className="artifact-viewer">
      <h3>{artifact.type} 详情</h3>
      {artifact.type === 'CODE' ? (
        <pre><code>{artifact.content}</code></pre>
      ) : (
        <pre>{JSON.stringify(artifact.content, null, 2)}</pre>
      )}
      {artifact.readOnly && <p className="read-only-note">只读模式</p>}
    </div>
  );
};

export default ArtifactViewer;

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getArchitecture, confirmArchitecture } from '../api/projects';

const ArchitectureReviewPanel: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [architectureDraft, setArchitectureDraft] = useState<any>(null);
  const [isConfirmed, setIsConfirmed] = useState(false);

  useEffect(() => {
    getArchitecture(projectId!).then(res => setArchitectureDraft(res.architectureContent));
  }, [projectId]);

  const handleConfirm = async () => {
    await confirmArchitecture(projectId!, { isConfirmed: true });
    setIsConfirmed(true);
  };

  if (!architectureDraft) return <div>加载架构设计中...</div>;
  if (isConfirmed) return <div>架构已确认，进入编码阶段...</div>;

  return (
    <div className="architecture-review">
      <h2>系统架构设计</h2>
      <pre>{JSON.stringify(architectureDraft, null, 2)}</pre>
      <button onClick={handleConfirm}>确认架构</button>
      <button>反馈修改意见</button>
    </div>
  );
};

export default ArchitectureReviewPanel;

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getLatestTestReport } from '../api/projects';

const TestReportViewer: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [testReport, setTestReport] = useState<any>(null);

  useEffect(() => {
    const fetchReport = async () => {
      const report = await getLatestTestReport(projectId!);
      setTestReport(report);
    };
    fetchReport();
    const interval = setInterval(fetchReport, 10000); // 轮询测试结果
    return () => clearInterval(interval);
  }, [projectId]);

  if (!testReport) return <div>等待测试执行...</div>;

  return (
    <div className="test-report-viewer">
      <h2>测试报告</h2>
      <div className="pass-rate">通过率: {testReport.passRate}%</div>
      <table>
        <thead>
          <tr>
            <th>用例ID</th>
            <th>描述</th>
            <th>状态</th>
            <th>错误日志</th>
          </tr>
        </thead>
        <tbody>
          {testReport.testCases.map((tc: any) => (
            <tr key={tc.id} className={tc.status === 'PASS' ? 'pass' : 'fail'}>
              <td>{tc.id}</td>
              <td>{tc.description}</td>
              <td>{tc.status}</td>
              <td>{tc.errorLog || '-'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default TestReportViewer;

import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getBugLogs } from '../api/projects';

const BugLogViewer: React.FC = () => {
  const { projectId } = useParams<{ projectId: string }>();
  const [bugLogs, setBugLogs] = useState<any[]>([]);

  useEffect(() => {
    const fetchLogs = async () => {
      const logs = await getBugLogs(projectId!);
      setBugLogs(logs.bugLogs);
    };
    fetchLogs();
    const interval = setInterval(fetchLogs, 10000);
    return () => clearInterval(interval);
  }, [projectId]);

  return (
    <div className="bug-log-viewer">
      <h2>Bug修复记录</h2>
      <table>
        <thead>
          <tr>
            <th>Bug ID</th>
            <th>关联测试用例</th>
            <th>修复日期</th>
            <th>修复方式</th>
            <th>程序名</th>
          </tr>
        </thead>
        <tbody>
          {bugLogs.map(bug => (
            <tr key={bug.bugId}>
              <td>{bug.bugId}</td>
              <td>{bug.failedTestCaseId}</td>
              <td>{new Date(bug.fixDate).toLocaleString()}</td>
              <td>{bug.fixMethod}</td>
              <td>{bug.programName}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default BugLogViewer;

