const BASE_URL = '/api/projects';

async function request(path: string, options?: RequestInit) {
  const response = await fetch(`${BASE_URL}${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  if (!response.ok) throw new Error(`API error: ${response.status}`);
  return response.json();
}

export const createProject = (data: { requirement: string }) =>
  request('', { method: 'POST', body: JSON.stringify(data) });

export const getPRD = (projectId: string) =>
  request(`/${projectId}/prd`);

export const submitPRD = (projectId: string, data: { prdContent: any; isConfirmed: boolean }) =>
  request(`/${projectId}/prd`, { method: 'POST', body: JSON.stringify(data) });

export const getTeamMembers = () =>
  request('/team-members'); // 假设存在获取成员的API

export const submitRoles = (projectId: string, data: { roles: any[] }) =>
  request(`/${projectId}/roles`, { method: 'POST', body: JSON.stringify(data) });

export const getArchitecture = (projectId: string) =>
  request(`/${projectId}/architecture`);

export const confirmArchitecture = (projectId: string, data: { isConfirmed: boolean }) =>
  request(`/${projectId}/architecture/confirm`, { method: 'POST', body: JSON.stringify(data) });

export const getArtifacts = (projectId: string) =>
  request(`/${projectId}/artifacts`);

export const getArtifactDetail = (projectId: string, artifactId: string) =>
  request(`/${projectId}/artifacts/${artifactId}`);

export const getLatestTestReport = (projectId: string) =>
  request(`/${projectId}/test-reports/latest`);

export const getBugLogs = (projectId: string) =>
  request(`/${projectId}/bug-logs`);

export const getProjectStatus = (projectId: string) =>
  request(`/${projectId}/status`);

