import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import AutoDeliveryEntry from './components/AutoDeliveryEntry';
import ConversationPanel from './components/ConversationPanel';
import RoleAssignmentPanel from './components/RoleAssignmentPanel';
import ArchitectureReviewPanel from './components/ArchitectureReviewPanel';
import ProjectDashboard from './components/ProjectDashboard';

const App: React.FC = () => {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<AutoDeliveryEntry />} />
        <Route path="/project/:projectId/conversation" element={<ConversationPanel />} />
        <Route path="/project/:projectId/roles" element={<RoleAssignmentPanel />} />
        <Route path="/project/:projectId/architecture-review" element={<ArchitectureReviewPanel />} />
        <Route path="/project/:projectId/dashboard" element={<ProjectDashboard />} />
      </Routes>
    </BrowserRouter>
  );
};

export default App;

